import { createWorker, type Worker } from "tesseract.js";

/**
 * OCR 模块：识别手机屏幕截图中的文字及其坐标
 * 用于按文字定位按钮，替代固定坐标点击
 */

let worker: Worker | null = null;
let workerReady = false;

/** 单个识别结果 */
export interface OcrWord {
  text: string;
  x: number; // 文字中心 x（像素，原始截图坐标系）
  y: number; // 文字中心 y
  width: number;
  height: number;
  confidence: number;
}

/** 初始化 OCR worker（懒加载，只初始化一次）
 *  全部资源本地化：worker / wasm 核心 / 语言包都从本站加载，
 *  不依赖 jsdelivr 等国外 CDN，确保同事的电脑（含不翻墙的 Windows）也能正常识别。
 */
export async function ensureWorker(onLog: (msg: string) => void): Promise<Worker> {
  if (worker && workerReady) return worker;

  onLog("首次初始化 OCR 引擎（加载本地中文识别模型，约 10-20 秒，仅需一次）...");
  try {
    // 用页面基准 URL 构造绝对路径，保证 Vite 构建后（含 GitHub Pages 子路径）也正确
    const base = document.baseURI.replace(/\/$/, "");
    onLog(`OCR 资源根路径: ${base}`);
    worker = await createWorker("chi_sim+eng", 1, {
      // 关键：全部指定本地路径，避免浏览器去 jsdelivr 下载
      workerPath: `${base}/worker.min.js`,
      corePath: `${base}/tesseract-core`,
      langPath: `${base}/tessdata`,
      // 语言包直接加载 .traineddata（我们提供的是非 gzip 版本，否则会去找 .traineddata.gz 而 404）
      gzip: false,
      // 关闭 worker 内嵌 blob，改用本地 worker 文件
      workerBlobURL: false,
      logger: (m: any) => {
        // 打印所有状态，便于定位卡在哪一步
        if (m && m.status) {
          const pct = typeof m.progress === "number" ? Math.round(m.progress * 100) : "";
          onLog(`[OCR] ${m.status}${pct !== "" ? ` ${pct}%` : ""}`);
        }
      },
    });
    workerReady = true;
    onLog("OCR 引擎就绪");
    return worker;
  } catch (err) {
    worker = null;
    throw new Error(
      `OCR 初始化失败: ${err instanceof Error ? err.message : String(err)}`
    );
  }
}

/**
 * 识别图片中的文字，返回所有词条（含坐标）
 * @param image 图片数据（URL、Blob、ImageData、canvas 等 tesseract.js 支持的类型）
 */
export async function recognizeWords(
  image: Blob | string | HTMLImageElement | HTMLCanvasElement | ImageData,
  onLog: (msg: string) => void
): Promise<OcrWord[]> {
  const w = await ensureWorker(onLog);

  // 关键：必须传 output: { blocks: true }，否则 tesseract.js 只返回纯文本 text，
  // 不返回带坐标的 blocks/words 结构（导致无法按文字定位按钮）
  const ret = await w.recognize(image as any, {}, { text: true, blocks: true });
  const data = ret.data as any;

  // 诊断：打印 tesseract 返回的原始文本（若 words 为空但 text 有内容，说明解析环节出问题）
  const rawText = (data.text || "").trim();
  const rawBlockCount = data.blocks ? data.blocks.length : 0;
  if (rawBlockCount === 0) {
    onLog(`[OCR诊断] tesseract 原始文本长度=${rawText.length}，blocks数=${rawBlockCount}。原始文本前120字: "${rawText.slice(0, 120)}"`);
  }

  const words: OcrWord[] = [];
  // tesseract.js v7 结构：data.blocks[] -> paragraphs[] -> lines[] -> words[]
  // 需要递归展开，每个 word 有 { text, confidence, bbox: { x0,y0,x1,y1 } }
  const blocks = data.blocks;
  if (Array.isArray(blocks)) {
    for (const block of blocks) {
      const paragraphs = block.paragraphs || [];
      for (const para of paragraphs) {
        const lines = para.lines || [];
        for (const line of lines) {
          const lineWords = line.words || [];
          for (const wd of lineWords) {
            const bbox = wd.bbox;
            if (!bbox) continue;
            const x0 = bbox.x0, y0 = bbox.y0, x1 = bbox.x1, y1 = bbox.y1;
            const text = (wd.text || "").trim();
            if (text.length === 0) continue;
            words.push({
              text,
              x: Math.round((x0 + x1) / 2),
              y: Math.round((y0 + y1) / 2),
              width: Math.round(x1 - x0),
              height: Math.round(y1 - y0),
              confidence: wd.confidence || 0,
            });
          }
        }
      }
    }
  }

  // 过滤空文字
  return words.filter((w) => w.text.length > 0);
}

/**
 * 在识别结果中查找包含目标文字的词条（模糊匹配）
 * 返回所有匹配，按置信度/匹配度排序
 *
 * 匹配策略（抗 OCR 拆分）：
 * 1. 精确子串：某个词条完整包含 target
 * 2. 组合匹配：target 被空格拆成多个关键词，找到能覆盖所有关键词的「相邻词条簇」，
 *    返回该簇的中心点（用于长按钮文字被 OCR 拆成多行/多词的情况）
 */
export function findText(words: OcrWord[], target: string): OcrWord[] {
  const t = target.trim();
  if (!t) return [];

  // 1. 精确/子串匹配（忽略空格：OCR 可能把"全部线索"识别成"全 部 线索"）
  const tNoSpace = stripSpaces(t);
  const exact = words.filter((w) => stripSpaces(w.text).includes(tNoSpace));
  if (exact.length > 0) return exact;

  // 2. 关键词簇匹配：把 target 拆成关键词，看是否有相邻词条能覆盖
  const keywords = t
    .split(/[\s·、，。]+/)
    .map((k) => k.trim())
    .filter((k) => k.length > 0);
  if (keywords.length <= 1) {
    // 只有单个关键词时，退化为"包含关键词"匹配
    return words.filter((w) => stripSpaces(w.text).includes(keywords[0]));
  }

  // 找出每个关键词在屏幕上的所有词条位置
  // 若一组词条在垂直方向相近（同一行或相邻行）且能覆盖全部关键词，则视为命中
  const hits: OcrWord[] = [];
  // 按 y 排序后滑动窗口匹配
  const sorted = [...words].sort((a, b) => a.y - b.y || a.x - b.x);
  for (let i = 0; i < sorted.length; i++) {
    const cluster = [sorted[i]];
    const covered = new Set<number>();
    for (const k of keywords) {
      if (sorted[i].text.includes(k)) covered.add(keywords.indexOf(k));
    }
    // 向右扩展，收集同一行（y 接近）的词条
    for (let j = i + 1; j < sorted.length; j++) {
      if (Math.abs(sorted[j].y - sorted[i].y) > sorted[i].height * 1.5) break;
      cluster.push(sorted[j]);
      for (const k of keywords) {
        if (sorted[j].text.includes(k)) covered.add(keywords.indexOf(k));
      }
    }
    if (covered.size === keywords.length) {
      // 命中：返回簇的中心（这些词条合并后的中心点）
      const cx = Math.round(cluster.reduce((s, w) => s + w.x, 0) / cluster.length);
      const cy = Math.round(cluster.reduce((s, w) => s + w.y, 0) / cluster.length);
      const x0 = Math.min(...cluster.map((w) => w.x - w.width / 2));
      const x1 = Math.max(...cluster.map((w) => w.x + w.width / 2));
      const y0 = Math.min(...cluster.map((w) => w.y - w.height / 2));
      const y1 = Math.max(...cluster.map((w) => w.y + w.height / 2));
      hits.push({
        text: target,
        x: cx,
        y: cy,
        width: x1 - x0,
        height: y1 - y0,
        confidence: 1,
      });
      break; // 只取第一个命中的簇
    }
  }
  return hits;
}

/** 合并相邻词条，得到一段文字（用于判断页面） */
export function fullText(words: OcrWord[]): string {
  // 按 y 排序后按行拼接
  const sorted = [...words].sort((a, b) => a.y - b.y || a.x - b.x);
  return sorted.map((w) => w.text).join(" ");
}

/** 去除所有空白字符（空格、换行等），用于容错匹配 */
export function stripSpaces(s: string): string {
  return s.replace(/\s+/g, "");
}

/**
 * 判断「整屏文字」是否包含目标文字（忽略空格）
 * 解决 OCR 把"全部线索"识别成"全 部 线 索"（带空格）导致精确匹配失败的问题
 */
export function textContains(haystack: string, needle: string): boolean {
  const hs = stripSpaces(haystack);
  const nd = stripSpaces(needle);
  if (!nd) return false;
  // 1. 精确子串（忽略空格）
  if (hs.includes(nd)) return true;
  // 2. 容错匹配：needle 的每个字都必须按顺序出现在 haystack 中（允许中间夹杂 OCR 噪声字符）
  //    例如"全部线索"被识别成"全部 线 索"或"全部线 索xx"都能命中
  let i = 0;
  for (const ch of nd) {
    const idx = hs.indexOf(ch, i);
    if (idx < 0) return false;
    i = idx + 1;
  }
  return true;
}

/** 释放 OCR worker */
export async function releaseOcr(): Promise<void> {
  if (worker) {
    try {
      await worker.terminate();
    } catch {
      // ignore
    }
    worker = null;
    workerReady = false;
  }
}
