import "./style.css";
import {
  connectDevice,
  disconnectDevice,
  executeScriptStep,
  getAdbClientState,
  setOnDisconnected,
  setOnScreenshot,
  dumpUi,
  type Script,
} from "./adb-client";
import { getAllScripts } from "./script-data";

let isRunning = false;
let logs: string[] = [];

function render() {
  const app = document.getElementById("app")!;
  const state = getAdbClientState();

  app.innerHTML = `
    <div class="container">
      <header>
        <h1>短信自动化控制台</h1>
        <p class="subtitle">通过浏览器直接控制安卓手机，无需安装任何软件</p>
      </header>

      <section class="card">
        <h2>设备连接</h2>
        <div class="device-status">
          <div class="status-indicator ${state.connected ? "connected" : "disconnected"}"></div>
          <span class="status-text">
            ${state.connected ? `已连接: ${state.deviceName || state.serial}` : "未连接"}
          </span>
        </div>
        <div class="button-group">
          <button id="btn-connect" class="btn btn-primary" ${state.connected ? "disabled" : ""}>
            ${state.connected ? "已连接" : "连接手机"}
          </button>
          <button id="btn-disconnect" class="btn btn-secondary" ${!state.connected ? "disabled" : ""}>
            断开连接
          </button>
          <button id="btn-dump-ui" class="btn btn-secondary" ${!state.connected ? "disabled" : ""}>
            诊断：读页面控件树
          </button>
        </div>
        <div class="browser-notice">
          <p>请使用 Chrome、Edge 或其他 Chromium 内核浏览器</p>
          <p>手机需开启「开发者选项 → USB 调试」</p>
        </div>
      </section>

      <section class="card">
        <h2>选择脚本</h2>
        <div class="script-list">
          ${getAllScripts()
            .map(
              (script) => `
            <div class="script-item" data-id="${script.id}">
              <div class="script-info">
                <div class="script-name">${script.name}</div>
                <div class="script-desc">${script.description}</div>
                <div class="script-steps">${script.steps.length} 个步骤${script.loopSteps ? ` + 循环体 ${script.loopSteps.length} 步` : ""}</div>
              </div>
              <div class="script-run-area">
                ${script.loop ? `<input type="number" class="loop-count" id="loop-${script.id}" min="1" max="100" value="5" title="循环次数" />` : ""}
                <button class="btn btn-run" data-id="${script.id}" ${!state.connected || isRunning ? "disabled" : ""}>
                  ${isRunning ? "运行中..." : "运行"}
                </button>
              </div>
            </div>
          `
            )
            .join("")}
        </div>
      </section>

      <section class="card">
        <h2>手机屏幕预览</h2>
        <div class="screen-preview">
          <img id="screen-img" alt="手机屏幕截图将显示在这里" style="display:none; max-width:100%; border-radius:8px; border:1px solid #e0e0e0;" />
          <p id="screen-placeholder" class="screen-placeholder">脚本运行时，这里会实时显示手机屏幕截图</p>
        </div>
      </section>

      <section class="card">
        <h2>执行日志</h2>
        <div class="log-container">
          <pre id="log-output">${logs.join("\n") || "等待操作..."}</pre>
        </div>
        <div class="button-group">
          <button id="btn-clear-log" class="btn btn-secondary">清空日志</button>
        </div>
      </section>

      <footer>
        <p>纯前端实现，所有数据仅存储在本地浏览器中</p>
      </footer>
    </div>
  `;

  bindEvents();
}

function bindEvents() {
  const connectBtn = document.getElementById("btn-connect");
  const disconnectBtn = document.getElementById("btn-disconnect");
  const clearLogBtn = document.getElementById("btn-clear-log");
  const dumpUiBtn = document.getElementById("btn-dump-ui");

  connectBtn?.addEventListener("click", handleConnect);
  disconnectBtn?.addEventListener("click", handleDisconnect);
  clearLogBtn?.addEventListener("click", () => {
    logs = [];
    render();
  });
  dumpUiBtn?.addEventListener("click", handleDumpUi);

  document.querySelectorAll(".btn-run").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      const id = (e.currentTarget as HTMLElement).dataset.id;
      if (id) handleRunScript(id);
    });
  });
}

function addLog(msg: string) {
  const now = new Date().toLocaleTimeString();
  logs.push(`[${now}] ${msg}`);
  const logOutput = document.getElementById("log-output");
  if (logOutput) {
    logOutput.textContent = logs.join("\n");
    logOutput.scrollTop = logOutput.scrollHeight;
  }
}

async function handleConnect() {
  try {
    addLog("开始连接设备...");
    await connectDevice(addLog);
    render();
  } catch (err) {
    addLog(`连接失败: ${err instanceof Error ? err.message : String(err)}`);
  }
}

async function handleDisconnect() {
  try {
    addLog("正在断开连接...");
    await disconnectDevice();
    addLog("已断开");
    render();
  } catch (err) {
    addLog(`断开失败: ${err instanceof Error ? err.message : String(err)}`);
  }
}

async function handleDumpUi() {
  addLog("========== 诊断：读取当前页面控件树（uiautomator） ==========");
  try {
    const { nodes, isWebViewOnly } = await dumpUi(addLog);
    if (isWebViewOnly) {
      addLog("⚠ 结论：页面是 WebView 渲染，uiautomator 读不到内部文字 → 只能用 OCR");
    } else if (nodes.length === 0) {
      addLog("⚠ 结论：uiautomator 未读到任何文字控件（页面可能空白/纯图片/或已息屏）");
    } else {
      addLog(`✓ 结论：uiautomator 读到 ${nodes.length} 个文字控件，说明可用「读控件树」替代 OCR！`);
      for (const n of nodes.slice(0, 80)) {
        addLog(`  「${n.text}」(${n.x},${n.y})${n.clickable ? " [可点击]" : ""}`);
      }
    }
  } catch (err) {
    addLog(`读取失败: ${err instanceof Error ? err.message : String(err)}`);
  }
}

async function handleRunScript(scriptId: string) {
  if (isRunning) return;

  const script = getAllScripts().find((s) => s.id === scriptId);
  if (!script) {
    addLog(`未找到脚本: ${scriptId}`);
    return;
  }

  // 读取循环次数
  let loopCount = 1;
  if (script.loop) {
    const input = document.getElementById(`loop-${script.id}`) as HTMLInputElement | null;
    loopCount = Math.max(1, Math.min(100, parseInt(input?.value ?? "1", 10) || 1));
  }

  isRunning = true;
  render();
  addLog(`========== 开始执行: ${script.name} ==========`);

  try {
    // 初始化步骤
    for (let i = 0; i < script.steps.length; i++) {
      const step = script.steps[i];
      addLog(`--- 初始化 ${i + 1}/${script.steps.length}: ${step.desc || step.action} ---`);
      await executeScriptStep(step, addLog);
    }

    // 循环体
    if (script.loopSteps && script.loopSteps.length > 0) {
      for (let round = 1; round <= loopCount; round++) {
        addLog(`========== 第 ${round}/${loopCount} 轮 ==========`);

        // 每轮开始前检查设备是否仍连接
        const st = getAdbClientState();
        if (!st.connected) {
          throw new Error("设备已断开连接，脚本中止");
        }

        for (let i = 0; i < script.loopSteps.length; i++) {
          const step = script.loopSteps[i];
          addLog(`[${round}-${i + 1}/${script.loopSteps.length}] ${step.desc || step.action}`);
          await executeScriptStep(step, addLog);
        }
        addLog(`---------- 第 ${round} 轮完成 ----------`);
      }
    }

    addLog(`========== 脚本执行完毕 ==========`);
  } catch (err) {
    addLog(
      `========== 执行中断: ${err instanceof Error ? err.message : String(err)} ==========`
    );
  } finally {
    isRunning = false;
    render();
  }
}

// 初始化
setOnDisconnected(() => {
  addLog("设备连接已断开，请重新连接");
  render();
});

// 截图预览：每次截图后更新网页上的 <img>
setOnScreenshot((blob) => {
  const img = document.getElementById("screen-img") as HTMLImageElement | null;
  const placeholder = document.getElementById("screen-placeholder");
  if (!img) return;
  const url = URL.createObjectURL(blob);
  img.onload = () => URL.revokeObjectURL(url);
  img.src = url;
  img.style.display = "block";
  if (placeholder) placeholder.style.display = "none";
});

render();
