import { Adb, AdbDaemonTransport } from "@yume-chan/adb";
import AdbWebCredentialStore from "@yume-chan/adb-credential-web";
import { AdbDaemonWebUsbDeviceManager } from "@yume-chan/adb-daemon-webusb";
import { recognizeWords, findText, fullText, textContains, stripSpaces, type OcrWord } from "./ocr";

let currentAdb: Adb | null = null;

// 屏幕尺寸（连接时获取，用于把 OCR 坐标换算成实际 tap 坐标）
let screenWidth = 1080;
let screenHeight = 2160;

// 断开时的回调（由 main.ts 注册，用于刷新界面）
let onDisconnected: (() => void) | null = null;
export function setOnDisconnected(cb: () => void) {
  onDisconnected = cb;
}

// 截图回调（由 main.ts 注册，用于在网页上实时预览手机屏幕）
let onScreenshot: ((blob: Blob) => void) | null = null;
export function setOnScreenshot(cb: (blob: Blob) => void) {
  onScreenshot = cb;
}

export interface AdbClientState {
  connected: boolean;
  deviceName: string;
  serial: string;
}

export function getAdbClientState(): AdbClientState {
  return {
    connected: currentAdb !== null,
    deviceName: currentAdb?.banner?.model ?? "",
    serial: currentAdb?.serial ?? "",
  };
}

export async function connectDevice(
  onLog: (msg: string) => void
): Promise<AdbClientState> {
  const manager = AdbDaemonWebUsbDeviceManager.BROWSER;
  if (!manager) {
    throw new Error(
      "当前浏览器不支持 WebUSB。请使用 Chrome、Edge 或其他 Chromium 内核浏览器。"
    );
  }

  onLog("请在选择器中选择您的安卓手机...");
  const device = await manager.requestDevice();
  if (!device) {
    throw new Error("未选择设备");
  }

  onLog(`已选择设备: ${device.name} (${device.serial})`);
  onLog("正在连接...");

  const connection = await device.connect();
  onLog("连接已建立，正在进行身份认证...");
  onLog("请在手机上确认 RSA 密钥授权（首次连接需要）...");

  const credentialStore = new AdbWebCredentialStore("sms-automation");
  const transport = await AdbDaemonTransport.authenticate({
    serial: device.serial,
    connection,
    credentialStore,
  });

  onLog("认证成功！");
  currentAdb = new Adb(transport);

  // 获取屏幕尺寸
  try {
    const sizeOut = await currentAdb.subprocess.noneProtocol.spawnWaitText(
      "wm size"
    );
    const m = sizeOut.match(/(\d+)\s*x\s*(\d+)/);
    if (m) {
      screenWidth = parseInt(m[1], 10);
      screenHeight = parseInt(m[2], 10);
      onLog(`屏幕分辨率: ${screenWidth} x ${screenHeight}`);
    }
  } catch {
    // 用默认值
  }

  // 连接成功后，双保险防止脚本执行中息屏：
  // 1. 把屏幕超时调到 30 分钟（最可靠，不依赖是否插电）
  // 2. 开启"充电时屏幕常亮"（插电时兜底）
  try {
    await currentAdb.subprocess.noneProtocol.spawnWaitText(
      "settings put system screen_off_timeout 1800000"
    );
    onLog("已将屏幕熄屏时间临时调至 30 分钟（脚本跑完会恢复）");
  } catch {
    onLog("提示：未能调整熄屏时间，请手动把手机屏幕超时调长");
  }
  try {
    await currentAdb.subprocess.noneProtocol.spawnWaitText(
      "settings put global stay_on_while_plugged_in 7"
    );
    onLog("已开启「充电时屏幕常亮」（插电时兜底）");
  } catch {
    onLog("提示：未能开启充电常亮，请保持手机插着充电线");
  }

  // 监听断开
  transport.disconnected.then(() => {
    onLog("设备已断开连接");
    currentAdb = null;
    if (onDisconnected) onDisconnected();
  });

  const state = getAdbClientState();
  onLog(`已连接到: ${state.deviceName || "未知设备"} (${state.serial})`);
  return state;
}

export async function disconnectDevice(): Promise<void> {
  if (currentAdb) {
    try {
      // 恢复屏幕超时为 30 秒（默认常见值）
      await currentAdb.subprocess.noneProtocol.spawnWaitText(
        "settings put system screen_off_timeout 30000"
      );
    } catch {
      // ignore
    }
    try {
      await currentAdb.subprocess.noneProtocol.spawnWaitText(
        "settings put global stay_on_while_plugged_in 0"
      );
    } catch {
      // ignore
    }
    await currentAdb.close();
    currentAdb = null;
  }
}

export async function sendShellCommand(
  command: string,
  onLog: (msg: string) => void
): Promise<string> {
  if (!currentAdb) {
    throw new Error("未连接到设备，请先连接手机");
  }

  onLog(`执行: ${command}`);
  try {
    const output = await currentAdb.subprocess.noneProtocol.spawnWaitText(
      command
    );
    if (output.trim()) {
      onLog(`输出: ${output.trim()}`);
    }
    return output;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    onLog(`错误: ${msg}`);
    throw err;
  }
}

/** 发送命令但不打印输出（内部用，避免日志刷屏） */
async function runShell(command: string): Promise<string> {
  if (!currentAdb) throw new Error("未连接设备");
  return currentAdb.subprocess.noneProtocol.spawnWaitText(command);
}

/**
 * 用 uiautomator 读取当前页面的控件树（XML），解析出所有带文字的节点。
 * 这是"读页面底层代码"的方式，文字精确、坐标精确，绕开 OCR。
 * 但仅对「原生控件渲染」的页面有效；若页面是 WebView 渲染（如 uni-app 页面），
 * 可能只吐出一个 WebView 容器，读不到里面的具体文字。
 *
 * 返回：{ nodes: 带文字的节点列表, raw: 原始 XML, isWebViewOnly: 是否只有WebView壳 }
 */
export async function dumpUi(
  onLog: (msg: string) => void
): Promise<{ nodes: { text: string; x: number; y: number; clickable: boolean }[]; raw: string; isWebViewOnly: boolean }> {
  if (!currentAdb) throw new Error("未连接设备");

  const dumpPath = "/sdcard/window_dump.xml";

  // 1. 导出控件树。uiautomator dump 常把 "dumped to..." 打到 stderr 并返回非零退出码，
  //    导致 spawnWaitText 抛异常，但 XML 实际已生成。所以这里先清空旧文件、执行、再直接读文件。
  try {
    await runShell(`rm -f ${dumpPath}`);
  } catch {
    // ignore
  }
  let dumpCmd = `uiautomator dump ${dumpPath}`;
  let dumped = false;
  try {
    await runShell(dumpCmd);
    dumped = true;
  } catch {
    // 抛异常不代表失败，继续尝试读文件
  }
  // 若没成功，尝试备用路径
  if (!dumped) {
    try {
      await runShell(`uiautomator dump /data/local/tmp/window_dump.xml`);
      dumped = true;
    } catch {
      // ignore
    }
  }

  // 2. 读取 XML 内容（用 sed 兜底，cat 在某些 ROM 上对超长单行 XML 有问题）
  let raw = "";
  try {
    raw = await runShell(`cat ${dumpPath} 2>/dev/null`);
  } catch {
    raw = "";
  }
  if (!raw || raw.trim().length === 0) {
    try {
      raw = await runShell(`cat /data/local/tmp/window_dump.xml 2>/dev/null`);
    } catch {
      raw = "";
    }
  }
  if (!raw || raw.trim().length === 0 || !raw.includes("<node")) {
    throw new Error("uiautomator 未生成有效控件树 XML（该 ROM 可能不支持）");
  }

  // 3. 解析：提取所有带 text 属性且非空的节点
  const nodes: { text: string; x: number; y: number; clickable: boolean }[] = [];
  const attrRegex = /<node\b[^>]*>/g;
  let m: RegExpExecArray | null;
  while ((m = attrRegex.exec(raw)) !== null) {
    const tag = m[0];
    const textMatch = tag.match(/text="([^"]*)"/);
    const boundsMatch = tag.match(/bounds="\[(\d+),(\d+)\]\[(\d+),(\d+)\]"/);
    if (!textMatch || !boundsMatch) continue;
    const text = textMatch[1].trim();
    if (!text) continue;
    const x0 = parseInt(boundsMatch[1], 10);
    const y0 = parseInt(boundsMatch[2], 10);
    const x1 = parseInt(boundsMatch[3], 10);
    const y1 = parseInt(boundsMatch[4], 10);
    // 过滤「幽灵节点」：bounds=[0,0][0,0] 的隐藏/缓存节点（实测 2026-10-16，
    // 老板帮「去联系」弹窗里每个「发短信/打电话/加微信」都混着 5 个零面积幽灵节点，
    // 它们无法点击，混进匹配列表会导致 index:0 点到屏幕 (0,0) 空白处）
    if (x1 - x0 <= 0 || y1 - y0 <= 0) continue;
    nodes.push({
      text,
      x: Math.round((x0 + x1) / 2),
      y: Math.round((y0 + y1) / 2),
      clickable: /clickable="true"/.test(tag),
    });
  }

  // 4. 判断是否只有 WebView 壳（读不到内部文字）
  const isWebViewOnly = nodes.length === 0 && /WebView|webview/i.test(raw);

  return { nodes, raw, isWebViewOnly };
}

/**
 * 截图，返回 PNG 二进制（Uint8Array）
 */
export async function screencap(): Promise<Blob> {
  if (!currentAdb) throw new Error("未连接设备");
  const bytes = await currentAdb.subprocess.noneProtocol.spawnWait("screencap -p");
  return new Blob([bytes], { type: "image/png" });
}

/**
 * 截图并 OCR 识别，返回文字词条（坐标已换算到实际屏幕像素）
 */
export async function screenshotAndOcr(
  onLog: (msg: string) => void
): Promise<{ words: OcrWord[]; text: string; blob: Blob; brightness: number }> {
  const blob = await screencap();
  // 触发截图回调，让网页实时预览手机屏幕
  if (onScreenshot) {
    try {
      onScreenshot(blob);
    } catch {
      // ignore
    }
  }
  // 把 PNG 转成 Image，再画到 canvas 供 OCR
  const img = await loadImage(blob);

  // 关键：tesseract 对高分辨率原图识别中文效果差，先把图放大 2 倍再识别
  // （放大后文字更大更清晰，能显著提高识别率；同时用独立 canvas 避免影响亮度计算）
  const scale = 2;
  const ocrCanvas = document.createElement("canvas");
  ocrCanvas.width = img.naturalWidth * scale;
  ocrCanvas.height = img.naturalHeight * scale;
  const octx = ocrCanvas.getContext("2d")!;
  octx.imageSmoothingEnabled = true;
  octx.imageSmoothingQuality = "high";
  octx.drawImage(img, 0, 0, ocrCanvas.width, ocrCanvas.height);

  const words = await recognizeWords(ocrCanvas, onLog);
  // OCR 是在放大 scale 倍的图上做的，坐标要缩回原始屏幕坐标（1080x2160）
  const scaledWords = words.map((w) => ({
    ...w,
    x: Math.round(w.x / scale),
    y: Math.round(w.y / scale),
    width: Math.round(w.width / scale),
    height: Math.round(w.height / scale),
  }));
  const text = fullText(scaledWords);

  // 用原尺寸 canvas 计算亮度（供上层判断黑屏/白屏）
  const canvas = document.createElement("canvas");
  canvas.width = img.naturalWidth;
  canvas.height = img.naturalHeight;
  const ctx = canvas.getContext("2d")!;
  ctx.drawImage(img, 0, 0);
  const { data } = ctx.getImageData(0, 0, canvas.width, canvas.height);
  let sum = 0;
  const step = Math.max(1, Math.floor(data.length / 4000));
  for (let i = 0; i < data.length; i += step * 4) {
    sum += data[i] + data[i + 1] + data[i + 2];
  }
  const samples = Math.floor(data.length / (step * 4)) || 1;
  const brightness = sum / (samples * 3);

  // 诊断：识别为空时，帮助定位是黑屏还是白屏
  if (scaledWords.length === 0) {
    onLog(
      `[诊断] OCR 结果为空。截图 ${canvas.width}x${canvas.height}，平均亮度 ${brightness.toFixed(1)}（0=纯黑，255=纯白）`
    );
    if (brightness < 10) {
      onLog("[诊断] 疑似黑屏/息屏！截图几乎全黑");
    } else if (brightness > 245) {
      onLog("[诊断] 疑似白屏/空白页！截图几乎全白");
    }
  }

  return { words: scaledWords, text, blob, brightness };
}

function loadImage(blob: Blob): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(blob);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve(img);
    };
    img.onerror = (e) => {
      URL.revokeObjectURL(url);
      reject(new Error("截图加载失败"));
    };
    img.src = url;
  });
}

/**
 * 统一的「在屏幕上找文字」入口：优先用 uiautomator 读控件树（精确、快），
 * 读不到（WebView 渲染 / 目标不在控件树）时回退到 OCR。
 * 返回：匹配到的词条（含坐标），以及用的哪种方式。
 */
interface FoundText {
  text: string;
  x: number;
  y: number;
  width: number;
  height: number;
  confidence: number;
}

async function findTextSmart(
  target: string,
  onLog: (msg: string) => void
): Promise<{ matches: FoundText[]; via: "ui" | "ocr" }> {
  onLog(`[识别方式] 查找「${target}」→ 优先尝试【uiautomator 控件树】`);
  // 先尝试 uiautomator 读控件树
  try {
    const { nodes, isWebViewOnly } = await dumpUi(onLog);
    if (isWebViewOnly) {
      onLog(`[识别方式] 当前页面仅 WebView（控件树读不到文字）→ 回退【OCR】`);
    } else if (nodes.length > 0) {
      // 在控件树里精确匹配（忽略空格）
      const tNoSpace = target.replace(/\s+/g, "");
      const hits = nodes.filter((n) => n.text.replace(/\s+/g, "").includes(tNoSpace));
      if (hits.length > 0) {
        onLog(`[识别方式] ✓ 命中【uiautomator 控件树】，共 ${hits.length} 处匹配`);
        return {
          via: "ui",
          matches: hits.map((h) => ({
            text: h.text,
            x: h.x,
            y: h.y,
            width: 10,
            height: 10,
            confidence: 1,
          })),
        };
      }
      onLog(`[识别方式] 控件树读到 ${nodes.length} 个文字节点，但未匹配到「${target}」→ 回退【OCR】`);
    } else {
      onLog(`[识别方式] 控件树为空 → 回退【OCR】`);
    }
  } catch (err) {
    onLog(`[识别方式] uiautomator 读取失败（${err instanceof Error ? err.message : String(err)}）→ 回退【OCR】`);
  }

  // 回退：OCR
  onLog(`[识别方式] 正在用【OCR】识别屏幕文字...`);
  const { words } = await screenshotAndOcr(onLog);
  const matches = findText(words, target);
  onLog(`[识别方式] 【OCR】识别完成，共 ${matches.length} 处匹配「${target}」`);
  return { via: "ocr", matches };
}

/**
 * 在屏幕上查找文字并点击其中心
 * 返回是否找到并点击成功
 */
export async function findAndTap(
  target: string,
  onLog: (msg: string) => void,
  opts: { index?: number; fuzzy?: boolean; randomTop?: number } = {}
): Promise<boolean> {
  const { matches, via } = await findTextSmart(target, onLog);

  let finalMatches = matches;

  // 如果精确匹配不到，且允许模糊，尝试逐字匹配（仅 OCR 场景）
  if (finalMatches.length === 0 && opts.fuzzy) {
    const chars = target.split("");
    const { words } = await screenshotAndOcr(onLog);
    finalMatches = words.filter((w) => chars.some((c) => c !== " " && w.text.includes(c)));
  }

  if (finalMatches.length === 0) {
    onLog(`未在屏幕上找到文字「${target}」（${via === "ui" ? "控件树" : "OCR"}）`);
    return false;
  }

  // 多匹配时按屏幕位置排序：y 从小到大（从上到下），y 相同再按 x。
  // 这样 index:0 恒等于「最上面」的那个——弹窗里 1~3 张卡片时固定点第一张卡的
  // 「发短信」（用户要求默认点最上面），不再依赖控件树/OCR 的文档顺序。
  // index:-1（随机）在排序后的列表里随机，行为不变。
  finalMatches = [...finalMatches].sort((a, b) => a.y - b.y || a.x - b.x);
  if (finalMatches.length > 1) {
    onLog(
      `「${target}」命中 ${finalMatches.length} 处，已按从上到下排序: y=[${finalMatches
        .map((m) => m.y)
        .join(", ")}]`
    );
  }

  // 随机模式若指定 randomTop，只在最前面 randomTop 个里随机：
  // 「复制话术并发送」这类页面，屏幕底部最后一个按钮常是「直接发送」，
  // 点到会真的直接发出（误触），故限定只在前两个可见按钮里随机，不碰最下面。
  if (
    opts.index === -1 &&
    opts.randomTop &&
    opts.randomTop > 0 &&
    finalMatches.length > opts.randomTop
  ) {
    onLog(
      `随机模式：已限定只在前 ${opts.randomTop} 个里选（共 ${finalMatches.length} 处，避开屏幕底部按钮）`
    );
  }

  let idx: number;
  if (opts.index === -1) {
    const topN =
      opts.randomTop && opts.randomTop > 0
        ? Math.min(opts.randomTop, finalMatches.length)
        : finalMatches.length;
    idx = Math.floor(Math.random() * topN); // -1 表示随机选一个（受 randomTop 上限约束）
  } else {
    idx = Math.min(opts.index ?? 0, finalMatches.length - 1);
  }
  const m = finalMatches[idx];
  onLog(`找到「${target}」（${via === "ui" ? "读控件树" : "OCR"}）→ 点击 (${m.x}, ${m.y})`);

  await runShell(`input tap ${m.x} ${m.y}`);
  return true;
}

/**
 * 判断当前屏幕是否包含某段文字（用于页面校验）
 * 优先 uiautomator，回退 OCR
 */
export async function screenHasText(
  target: string,
  onLog: (msg: string) => void
): Promise<boolean> {
  const { matches } = await findTextSmart(target, onLog);
  return matches.length > 0;
}

/**
 * 关闭广告弹窗（循环检测，直到目标文字出现或超时）
 * 适用于"打开 App 后先出现全屏开屏广告、再偶发弹窗广告"的场景。关键行为：
 * - 若屏幕上已出现「目标文字」→ 已进入干净页面，直接返回
 * - 识别为空且亮度极低 → 黑屏/息屏，主动唤醒解锁
 * - 识别为空但亮度较高 → App 还在加载（白屏/闪屏），继续等待，不误操作
 * - 检测到「跳过」等开屏广告标志词 → 仍处于开屏广告阶段（冷启动慢，时机不固定），只等待绝不点击
 * - 开屏广告消失后（无"跳过"），目标仍未出现 → 一律点上方空白关弹窗广告（不依赖关闭按钮位置）
 */
async function dismissAd(
  target: string,
  onLog: (msg: string) => void,
  opts: { timeout?: number; interval?: number; graceMs?: number } = {}
): Promise<boolean> {
  const timeout = opts.timeout ?? 20000;
  const interval = opts.interval ?? 2000;
  // 强制静默下限：进入循环后的前 graceMs 毫秒内，除"目标文字已出现"外，一律不点
  // （双保险：即使"跳过"标志没被识别出来，冷启动的开屏广告也大概率在这段时间内自动消失）
  const graceMs = opts.graceMs ?? 8000;
  const start = Date.now();

  // 开屏广告标志词：出现这些字说明还在全屏开屏广告阶段，绝不能点击
  const splashWords = ["跳过", "广告"];

  // 判断目标是否出现（优先读控件树，回退 OCR）
  const hasTarget = async (): Promise<boolean> => {
    try {
      const { matches } = await findTextSmart(target, onLog);
      return matches.length > 0;
    } catch {
      return false;
    }
  };

  onLog(`开始等待主页（检测「${target}」，最长 ${Math.round(timeout / 1000)} 秒，前 ${Math.round(graceMs / 1000)} 秒强制静默 + 动态识别开屏广告）...`);

  while (Date.now() - start < timeout) {
    const { words, text, brightness } = await screenshotAndOcr(onLog);

    // 1. 先算开屏广告标志词：实测（2026-10-16）开屏广告盖着时 uiautomator
    //    仍能读到底下 tab 栏的「首页」，若只看目标文字会在广告未消失时提前返回，
    //    导致下一步「找客雷达」点进广告的 CTA。命中标志词时一律先等广告消失。
    const splashHit = splashWords.some((w) => textContains(text, w));

    // 2. 目标文字已出现 且 无开屏广告标志 → 成功（优先 uiautomator 精确判断）
    if (!splashHit && (await hasTarget())) {
      onLog(`✓ 目标文字「${target}」已出现，已进入主页`);
      return true;
    }

    // 2. 识别为空且屏幕全黑 → 息屏，唤醒解锁
    if (words.length === 0 && brightness < 10) {
      onLog("识别为空且屏幕全黑，判定为息屏，唤醒并解锁...");
      await runShell("input keyevent 224");
      await new Promise((r) => setTimeout(r, 800));
      await runShell(`input swipe ${screenWidth / 2} ${Math.round(screenHeight * 0.83)} ${screenWidth / 2} ${Math.round(screenHeight * 0.28)} 300`);
      await new Promise((r) => setTimeout(r, 1200));
      continue;
    }

    // 3. 识别为空但屏幕是亮的（亮度高，App 还在加载白屏/闪屏）→ 只等，不误点
    if (words.length === 0 && brightness > 200) {
      onLog("屏幕亮但暂无文字（App 加载中/白屏），继续等待...");
      await new Promise((r) => setTimeout(r, interval));
      continue;
    }

    // 4. 检测到开屏广告标志词（"跳过"/"广告"）→ 仍处于全屏开屏广告阶段，绝不点击
    if (splashHit) {
      onLog("检测到开屏广告（含「跳过/广告」标志），等待其自动消失，不点击...");
      await new Promise((r) => setTimeout(r, interval));
      continue;
    }

    // 5. 强制静默期内：不管识别到什么，都不点（双保险等开屏广告消失）
    if (Date.now() - start < graceMs) {
      onLog("强制静默期内（等开屏广告消失，防冷启动延迟），暂不点击...");
      await new Promise((r) => setTimeout(r, interval));
      continue;
    }

    // 6. 开屏广告已消失、目标仍未出现 → 弹窗广告阶段（弹窗在屏幕正中央，必须手动关掉）
    //    实测：点弹窗正上方空白处(0.5w, 0.15h)即可关闭，且不会误触主页。
    //    不要用返回键——返回键会把整个页面退出去，反而错乱。
    onLog(
      `开屏广告已过、目标未出现（亮度 ${brightness.toFixed(0)}，识别 ${words.length} 个词条），点弹窗上方空白处关闭弹窗广告...`
    );
    await runShell(`input tap ${Math.round(screenWidth * 0.5)} ${Math.round(screenHeight * 0.15)}`);
    await new Promise((r) => setTimeout(r, 1500));
    if (await hasTarget()) {
      onLog(`✓ 点空白后目标文字「${target}」出现，弹窗已关闭`);
    } else {
      onLog("点空白后目标仍未出现，继续等待下一轮（可能弹窗还需时间消失）...");
    }
    await new Promise((r) => setTimeout(r, interval));
  }

  // 超时后再检查一次
  if (await hasTarget()) {
    onLog(`✓ 目标文字「${target}」出现（超时前最后一刻）`);
    return true;
  }

  onLog(`⚠ 等待主页超时：仍未检测到「${target}」`);
  return false;
}

/** 按返回键 */
async function pressBack(onLog: (msg: string) => void): Promise<void> {
  await sendShellCommand("input keyevent 4", onLog);
}

/** 唤醒并解锁（判断式） */
async function wakeUnlock(onLog: (msg: string) => void): Promise<void> {
  await runShell("input keyevent 224");
  await new Promise((r) => setTimeout(r, 600));

  const lockInfo = await runShell(
    "dumpsys window | grep -E 'mDreamingLockscreen|isStatusBarKeyguard|mCurrentFocus'"
  );
  const locked =
    /mDreamingLockscreen=true|isStatusBarKeyguard=true/i.test(lockInfo) ||
    /StatusBar/i.test(lockInfo);

  if (locked) {
    onLog("检测到锁屏，正在上滑解锁...");
    await runShell("input keyevent 82");
    await new Promise((r) => setTimeout(r, 400));
    await runShell(`input swipe ${screenWidth / 2} ${Math.round(screenHeight * 0.83)} ${screenWidth / 2} ${Math.round(screenHeight * 0.28)} 300`);
    await new Promise((r) => setTimeout(r, 1200));
  } else {
    onLog("屏幕已亮且已解锁，跳过解锁");
  }
}

/** 回到桌面（home 键） */
async function goHome(onLog: (msg: string) => void): Promise<void> {
  onLog("按 Home 键回到桌面");
  await runShell("input keyevent 3");
  await new Promise((r) => setTimeout(r, 1000));
}

/**
 * 可靠地杀死一个 App（force-stop + 验证 + 补刀）
 * uni-app / 部分应用 force-stop 后进程可能残留，这里做闭环验证
 */
async function killApp(pkg: string, onLog: (msg: string) => void): Promise<void> {
  if (!pkg) {
    onLog("警告: kill_app 缺少 package");
    return;
  }

  onLog(`强制关闭 App: ${pkg}`);
  await runShell(`am force-stop ${pkg}`).catch(() => {});
  await new Promise((r) => setTimeout(r, 1000));

  // 验证进程是否还活着（多进程应用可能有 :xxx 子进程，用 ps 全量查）
  let stillAlive = true;
  try {
    const ps = await runShell(`ps -A | grep ${pkg}`);
    stillAlive = ps.trim().length > 0 && !ps.includes("grep");
  } catch {
    // ps 可能无权限，改用 pidof
    try {
      const pid = await runShell(`pidof ${pkg}`);
      stillAlive = pid.trim().length > 0;
    } catch {
      stillAlive = false;
    }
  }

  if (stillAlive) {
    onLog("进程仍在运行，补刀强制杀死...");
    await runShell(`am kill ${pkg}`).catch(() => {});
    await new Promise((r) => setTimeout(r, 800));

    // 二次验证
    try {
      const pid2 = await runShell(`pidof ${pkg}`);
      stillAlive = pid2.trim().length > 0;
    } catch {
      stillAlive = false;
    }
  }

  if (stillAlive) {
    onLog(`警告: ${pkg} 进程仍存活（可能需要手动关闭，或该 App 为系统级受保护应用）`);
  } else {
    onLog(`✓ ${pkg} 已完全关闭`);
  }
}

export async function executeScriptStep(
  step: ScriptStep,
  onLog: (msg: string) => void
): Promise<void> {
  switch (step.action) {
    case "start_app": {
      const pkg = step.package ?? "";
      if (!pkg) {
        onLog("警告: start_app 缺少 package");
        break;
      }
      // 实测：老板帮的 Activity 非 exported，am start 会被 Permission Denial 拒绝；
      // monkey 走 launcher intent 冷启动最可靠（真机验证通过）
      await sendShellCommand(
        `monkey -p ${pkg} -c android.intent.category.LAUNCHER 1`,
        onLog
      );
      break;
    }
    case "tap": {
      await sendShellCommand(`input tap ${step.x} ${step.y}`, onLog);
      break;
    }
    case "text": {
      const text = (step.content ?? "").replace(/ /g, "%s");
      await sendShellCommand(`input text "${text}"`, onLog);
      break;
    }
    case "keyevent": {
      await sendShellCommand(`input keyevent ${step.key}`, onLog);
      break;
    }
    case "swipe": {
      await sendShellCommand(
        `input swipe ${step.x1} ${step.y1} ${step.x2} ${step.y2} ${step.duration ?? 300}`,
        onLog
      );
      break;
    }
    case "sleep": {
      onLog(`等待 ${step.ms}ms...`);
      await new Promise((r) => setTimeout(r, step.ms ?? 1000));
      break;
    }
    case "shell": {
      await sendShellCommand(step.command ?? "", onLog);
      break;
    }
    case "kill_app": {
      await killApp(step.package ?? "", onLog);
      break;
    }
    case "dismiss_ad": {
      await dismissAd(step.text ?? "", onLog, {
        timeout: step.timeout,
        interval: step.retryInterval,
        graceMs: step.graceMs,
      });
      break;
    }
    case "wake_unlock": {
      await wakeUnlock(onLog);
      break;
    }
    case "go_home": {
      await goHome(onLog);
      break;
    }
    case "back": {
      await pressBack(onLog);
      break;
    }
    case "find_and_tap": {
      // 按文字找并点击，找不到会重试 step.retry 次（每次间隔 step.retryInterval ms）
      // 点击后校验：若配置了 verify 文字，点完等 verifyText 出现才算成功，
      // 否则（verifyText 空）点完即算成功。
      const target = step.text ?? "";
      const retries = step.retry ?? 0;
      const interval = step.retryInterval ?? 2000;
      let ok = false;
      for (let i = 0; i <= retries; i++) {
        if (i > 0) {
          onLog(`第 ${i + 1} 次尝试查找「${target}」...`);
          await new Promise((r) => setTimeout(r, interval));
        }
        const clicked = await findAndTap(target, onLog, { index: step.index, fuzzy: step.fuzzy, randomTop: step.randomTop });
        if (!clicked) continue;
        // 点击后校验
        if (step.verifyText) {
          await new Promise((r) => setTimeout(r, step.verifyDelay ?? 1500));
          const appeared = await screenHasText(step.verifyText, onLog);
          if (appeared) {
            onLog(`✓ 点击后「${step.verifyText}」出现，操作成功`);
            ok = true;
            break;
          }
          onLog(`点击「${target}」后未出现「${step.verifyText}」，重试...`);
          continue;
        }
        ok = true;
        break;
      }
      if (!ok) {
        throw new Error(`多次尝试仍未完成「${target}」，脚本中止`);
      }
      break;
    }
    case "tap_coord": {
      // 坐标点击 + 点击后校验（用于弹窗/按钮读不到文字、只能用坐标点的场景）
      // 点完等 verifyText 出现才算成功；不出现则重试（重试前先检测是否卡死并 back 恢复）
      const x = step.x ?? 0;
      const y = step.y ?? 0;
      const retries = step.retry ?? 0;
      const interval = step.retryInterval ?? 2000;
      let ok = false;
      for (let i = 0; i <= retries; i++) {
        if (i > 0) {
          onLog(`第 ${i + 1} 次点击 (${x}, ${y})...`);
          await new Promise((r) => setTimeout(r, interval));
        }
        onLog(`点击 (${x}, ${y})${step.desc ? " — " + step.desc : ""}`);
        await runShell(`input tap ${x} ${y}`);
        if (!step.verifyText) {
          ok = true;
          break;
        }
        await new Promise((r) => setTimeout(r, step.verifyDelay ?? 2000));
        const appeared = await screenHasText(step.verifyText, onLog);
        if (appeared) {
          onLog(`✓ 点击后「${step.verifyText}」出现，操作成功`);
          ok = true;
          break;
        }
        onLog(`点击后未出现「${step.verifyText}」，重试...`);
      }
      if (!ok) {
        throw new Error(`多次点击 (${x},${y}) 后仍未出现「${step.verifyText}」，脚本中止`);
      }
      break;
    }
    case "ensure_visible": {
      // 确保某段文字可见：先 dump 找；找不到就向下滚动再找，直到找到或超时
      const target = step.text ?? "";
      const maxScroll = step.retry ?? 5;
      const interval = step.retryInterval ?? 1500;
      let found = false;
      for (let i = 0; i <= maxScroll; i++) {
        if (await screenHasText(target, onLog)) {
          onLog(`「${target}」已可见`);
          found = true;
          break;
        }
        if (i < maxScroll) {
          onLog(`「${target}」不可见，向下滚动查找 (${i + 1}/${maxScroll})...`);
          await runShell(`input swipe ${Math.round(screenWidth * 0.5)} ${Math.round(screenHeight * 0.75)} ${Math.round(screenWidth * 0.5)} ${Math.round(screenHeight * 0.3)} 400`);
          await new Promise((r) => setTimeout(r, interval));
        }
      }
      if (!found) {
        throw new Error(`滚动 ${maxScroll} 次后仍未找到「${target}」，脚本中止`);
      }
      break;
    }
    case "wait_for_text": {
      // 等待屏幕上出现某段文字（页面加载完成标志）
      const target = step.text ?? "";
      const timeout = step.timeout ?? 10000;
      const interval = step.retryInterval ?? 1500;
      const start = Date.now();
      let found = false;
      while (Date.now() - start < timeout) {
        const has = await screenHasText(target, onLog);
        if (has) {
          found = true;
          onLog(`检测到页面文字「${target}」，页面已就绪`);
          break;
        }
        await new Promise((r) => setTimeout(r, interval));
      }
      if (!found) {
        onLog(`警告: 等待 ${timeout}ms 后仍未出现「${target}」，继续执行`);
      }
      break;
    }
    case "random_tap": {
      const options = step.options ?? [];
      if (options.length === 0) {
        onLog("警告: random_tap 缺少 options 配置");
        break;
      }
      const picked = options[Math.floor(Math.random() * options.length)];
      onLog(`随机选中坐标 (${picked.x}, ${picked.y})`);
      await sendShellCommand(`input tap ${picked.x} ${picked.y}`, onLog);
      break;
    }
    case "dump_ui": {
      // 诊断：读当前页面控件树，判断能否用 uiautomator 替代 OCR
      try {
        const { nodes, isWebViewOnly } = await dumpUi(onLog);
        if (isWebViewOnly) {
          onLog("⚠ 页面是 WebView 渲染，uiautomator 读不到内部文字，只能继续用 OCR");
        } else if (nodes.length === 0) {
          onLog("uiautomator 未读到任何带文字控件（可能页面空白或纯图片）");
        } else {
          onLog(`✓ uiautomator 读到 ${nodes.length} 个文字控件：`);
          for (const n of nodes.slice(0, 50)) {
            onLog(`  「${n.text}」(${n.x},${n.y})${n.clickable ? " 可点击" : ""}`);
          }
        }
      } catch (err) {
        onLog(`uiautomator 读取失败: ${err instanceof Error ? err.message : String(err)}`);
      }
      break;
    }
    case "send_sms_to_lead": {
      // 从当前线索详情页控件树精确读出手机号（uiautomator，不用 OCR），
      // 然后用 SENDTO intent 直接跳系统短信页并预填随机话术。
      // 实测：App 内「去联系→发短信」弹窗按钮点击无响应（试了6次），
      // 但详情页手机号可精确读到，SENDTO 跳转+预填中文话术真机验证通过。
      const texts = step.smsTexts ?? [];
      if (texts.length === 0) {
        throw new Error("send_sms_to_lead 缺少 smsTexts（话术列表）配置");
      }
      const msg = texts[Math.floor(Math.random() * texts.length)];
      let phone = "";
      try {
        const { nodes } = await dumpUi(onLog);
        for (const n of nodes) {
          const m = n.text.match(/1[3-9]\d{9}/);
          if (m) {
            phone = m[0];
            break;
          }
        }
      } catch (err) {
        throw new Error(`读取详情页控件树失败: ${err instanceof Error ? err.message : String(err)}`);
      }
      if (!phone) {
        throw new Error("未在详情页读到手机号（可能未进入详情页或页面未加载完）");
      }
      onLog(`✓ 读到手机号 ${phone}，随机话术: ${msg}`);
      // 话术里不能有双引号（会破坏 shell 引号），生成话术时已规避；空格用 %s 会被 input text 处理，
      // 但 am start 的 --es 直接传字符串即可，用双引号包裹
      await sendShellCommand(
        `am start -a android.intent.action.SENDTO -d "smsto:${phone}" --es sms_body "${msg}"`,
        onLog
      );
      break;
    }
    default:
      onLog(`未知操作: ${(step as any).action}`);
  }
}

export interface ScriptStep {
  action:
    | "start_app"
    | "tap"
    | "text"
    | "keyevent"
    | "swipe"
    | "sleep"
    | "shell"
    | "back"
    | "random_tap"
    | "wake_unlock"
    | "go_home"
    | "find_and_tap"
    | "wait_for_text"
    | "tap_coord"
    | "ensure_visible"
    | "kill_app"
    | "dismiss_ad"
    | "dump_ui"
    | "send_sms_to_lead";
  desc?: string;
  // start_app
  package?: string;
  activity?: string;
  // tap
  x?: number;
  y?: number;
  // text / find_and_tap / wait_for_text
  text?: string;
  content?: string;
  // find_and_tap
  index?: number;
  fuzzy?: boolean;
  // 随机模式(index:-1)下，只在最前面的 randomTop 个匹配里随机（避开底部按钮误触）
  randomTop?: number;
  retry?: number;
  retryInterval?: number;
  // find_and_tap / tap_coord 点击后校验：等待此文字出现才算成功
  verifyText?: string;
  verifyDelay?: number;
  // wait_for_text
  timeout?: number;
  // dismiss_ad
  graceMs?: number;
  // keyevent
  key?: string;
  // swipe
  x1?: number;
  y1?: number;
  x2?: number;
  y2?: number;
  duration?: number;
  // sleep
  ms?: number;
  // shell
  command?: string;
  // random_tap
  options?: { x: number; y: number }[];
  // send_sms_to_lead：随机话术列表（话术内不要包含双引号）
  smsTexts?: string[];
}

export interface Script {
  id: string;
  name: string;
  description: string;
  /** 初始化步骤：只执行一次 */
  steps: ScriptStep[];
  /** 循环体步骤：按用户填写的次数重复执行 */
  loopSteps?: ScriptStep[];
  /** 支持循环：为 true 时网页上显示次数输入框 */
  loop?: boolean;
}
