/**
 * 从 localStorage 加载自定义脚本
 */
export function loadCustomScripts(): Script[] {
  try {
    const raw = localStorage.getItem("sms-automation-scripts");
    if (raw) {
      return JSON.parse(raw) as Script[];
    }
  } catch {
    // ignore
  }
  return [];
}

/**
 * 保存自定义脚本到 localStorage
 */
export function saveCustomScripts(scripts: Script[]): void {
  localStorage.setItem("sms-automation-scripts", JSON.stringify(scripts));
}

/**
 * 获取所有脚本（预设 + 自定义）
 */
export function getAllScripts(): Script[] {
  return [...defaultScripts, ...loadCustomScripts()];
}
